export const FactoryIcon = ({ name }: { name: keyof typeof icons }) => {
  const icon = icons[name];
  return (
    <svg viewBox={icon.viewBox} aria-hidden="true" focusable="false">
      {icon.paths.map((path, index) => (
        <path key={index} {...path} />
      ))}
    </svg>
  );
};
